mapper.select:
select e.employee_id as employeeId , e.member_id as memberId , e.department_id as departmentId , m.user_id as userId , m.member_name as memberName , m.nickname as nickname , m.phone as phone , m.email as email , m.user_type as userType , m.login_type as loginType , e.employee_no as employeeNo , d.department_name as departmentName , d.department_code as departmentCode , e.position_name as positionName , e.duty_name as dutyName , e.status as status , e.hired_at as hiredAt , e.retired_at as retiredAt , e.created_at as createdAt , e.updated_at as updatedAt from employee e join app_member m on e.member_id = m.member_id join department d on e.department_id = d.department_id where 1 = 1
and ( m.member_name ilike '%' || #{keyword} || '%' or m.user_id ilike '%' || #{keyword} || '%' or e.employee_no ilike '%' || #{keyword} || '%' or m.email ilike '%' || #{keyword} || '%' )
and e.department_id = #{departmentId}
and m.user_type = #{userType}
and e.status = #{status}
order by e.employee_id desc

mapper.insert:
insert into app_member (
      user_id
    , password
    , member_name
    , nickname
    , phone
    , email
    , user_type
    , login_type
    , status
    , created_at
    , updated_at
) values (
      #{userId}
    , #{password}
    , #{memberName}
    , #{nickname}
    , nullif(#{phone}, '')
    , #{email}
    , #{userType}
    , 'LOCAL'
    , 'ACTIVE'
    , current_timestamp
    , current_timestamp
)

insert into employee (
      member_id
    , department_id
    , employee_no
    , position_name
    , duty_name
    , status
    , hired_at
    , created_at
    , updated_at
) values (
      #{memberId}
    , #{departmentId}
    , #{employeeNo}
    , #{positionName}
    , #{dutyName}
    , coalesce(nullif(#{status}, ''), 'ACTIVE')
    , #{hiredAt}
    , current_timestamp
    , current_timestamp
)

mapper.select:
select count(*)
  from app_member m
  left join employee e
    on m.member_id = e.member_id
 where m.user_id = #{userId}

   and coalesce(e.employee_id, -1) != #{excludeEmployeeId}

select count(*)
  from app_member m
  left join employee e
    on m.member_id = e.member_id
 where m.email = #{email}

   and coalesce(e.employee_id, -1) != #{excludeEmployeeId}

select count(*)
  from employee e
 where e.employee_no = #{employeeNo}

   and e.employee_id != #{excludeEmployeeId}
